import React, { useRef, useState, useEffect } from "react";
import styled from "styled-components";
import { useNavigate } from "react-router-dom";
import SalonCard from "../../components/common/SalonCard";
import TabBar from "../../components/common/TabBar";
import promotionHeader from "../../images/promotionHeader.png";

/* ============================================================
   Styled Components
============================================================ */
const PageWrapper = styled.div`
  background-color: #f2dcdc;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
`;

const ContentWrapper = styled.div`
  width: 100%;
  max-width: 1600px;
  padding: 20px 3%;
  box-sizing: border-box;
`;

const WelcomeText = styled.h1`
  font-family: "Inter", sans-serif;
  font-size: 48px;
  font-weight: 700;
  color: #4A5074;
  margin: 40px 0 30px;
`;

/* ===== Offers Carousel ===== */
const OfferCarouselWrapper = styled.div`
  width: 100%;
  max-width: 1600px;
  overflow: hidden;
  margin-bottom: 40px;
  position: relative;
`;

const OfferTrack = styled.div`
  display: flex;
  width: 100%;
  height: 220px;
  transition: transform 0.5s ease;
`;

const PromoBanner = styled.div`
  width: 100%;
  height: 220px;
  border-radius: 12px;
  background-size: cover;
  background-position: center;
  position: relative;
  overflow: hidden;
  flex-shrink: 0;
`;

const BannerImage = styled.img`
  width: 100%;
  height: 100%;
  object-fit: cover;
  border-radius: 12px;
`;

const OfferTextContainer = styled.div`
  position: absolute;
  left: 20px;
  bottom: 70px;
  color: #ffffff;
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.7);
`;

const OfferTitle = styled.h3`
  font-size: 20px;
  font-weight: 700;
  margin: 0 0 4px 0;
`;

const OfferDiscount = styled.div`
  font-size: 16px;
  font-weight: 600;
  margin-bottom: 4px;
`;

const OfferServices = styled.div`
  font-size: 14px;
  font-weight: 400;
`;

const SalonNameText = styled.div`
  position: absolute;
  right: 20px;
  bottom: 20px;
  font-size: 22px;
  font-weight: 800;
  color: #ffffff;
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.7);
`;

const BookNowButton = styled.button`
  position: absolute;
  bottom: 20px;
  left: 20px;
  background-color: #0b1c36;
  color: white;
  font-size: 16px;
  font-weight: 500;
  padding: 10px 18px;
  border-radius: 8px;
  border: none;
  cursor: pointer;
  transition: 0.2s ease;
  &:hover {
    opacity: 0.9;
  }
`;

const DotsWrapper = styled.div`
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-top: 10px;
  margin-bottom: 10px;
`;

const Dot = styled.button<{ active: boolean }>`
  width: 10px;
  height: 10px;
  border-radius: 50%;
  border: none;
  background-color: ${(p) => (p.active ? "#0b1c36" : "#d3d3d3")};
  cursor: pointer;
`;

/* ===== Salon Categories ===== */
const CategoryHeader = styled.div`
  background-color: #fff;
  display: inline-block;
  padding: 8px 18px;
  border-radius: 10px;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.05);
  margin-bottom: 16px;
`;

const SectionTitle = styled.h2`
  font-size: 22px;
  font-weight: 700;
  color: #4A5074;
  margin: 0;
`;

const ScrollWrapper = styled.div`
  display: flex;
  width: 100%;
  margin-bottom: 40px;
`;

const HorizontalScroll = styled.div`
  display: flex;
  gap: 18px;
  overflow-x: auto;
  width: 100%;
  padding-bottom: 10px;
`;

/* ============================================================
   Component
============================================================ */
const HomePage: React.FC = () => {
  const navigate = useNavigate();

  /* ===== Fetch Salons from Backend ===== */
  const [salons, setSalons] = useState([]);
  const [loadingSalons, setLoadingSalons] = useState(true);

  useEffect(() => {
    const fetchSalons = async () => {
      try {
        const res = await fetch("http://localhost:5000/api/businesses");
        const data = await res.json();
        setSalons(data);
      } catch (err) {
        console.error("Error fetching salons:", err);
      } finally {
        setLoadingSalons(false);
      }
    };

    fetchSalons();
  }, []);

  /* ===== Static Offers (for now) ===== */
  const offers = [
    {
      id: 1,
      salonId: null,
      title: "Glow-Up Hair Package",
      discountText: "20% OFF",
      servicesText: "Haircut • Blowdry • Treatment",
      image: promotionHeader,
    },
    {
      id: 2,
      salonId: null,
      title: "Weekend Pamper Deal",
      discountText: "15% OFF",
      servicesText: "Facial • Manicure • Pedicure",
      image: promotionHeader,
    },
    {
      id: 3,
      salonId: null,
      title: "Grooming Essentials",
      discountText: "25% OFF",
      servicesText: "Haircut + Shave • Facial",
      image: promotionHeader,
    },
  ];

  const [activeOfferIndex, setActiveOfferIndex] = useState(0);

  useEffect(() => {
    if (offers.length === 0) return;

    const interval = setInterval(() => {
      setActiveOfferIndex((prev) => (prev + 1) % offers.length);
    }, 10000);

    return () => clearInterval(interval);
  }, []);

  /* ===== Loading State ===== */
  if (loadingSalons) {
    return (
      <PageWrapper>
        <TabBar type="customer" />
        <ContentWrapper>
          <WelcomeText>Loading salons…</WelcomeText>
        </ContentWrapper>
      </PageWrapper>
    );
  }

  return (
    <PageWrapper>
      <TabBar type="customer" />
      <ContentWrapper>
        <WelcomeText>Welcome Back!</WelcomeText>

        {/* ===== Offers Carousel ===== */}
        <OfferCarouselWrapper>
          <OfferTrack
            style={{
              transform: `translateX(-${activeOfferIndex * 100}%)`,
            }}
          >
            {offers.map((offer) => (
              <PromoBanner key={offer.id}>
                <BannerImage src={offer.image} alt={offer.title} />

                <OfferTextContainer>
                  <OfferTitle>{offer.title}</OfferTitle>
                  <OfferDiscount>{offer.discountText}</OfferDiscount>
                  <OfferServices>{offer.servicesText}</OfferServices>
                </OfferTextContainer>

                <BookNowButton>Book Now</BookNowButton>
              </PromoBanner>
            ))}
          </OfferTrack>
        </OfferCarouselWrapper>

        <DotsWrapper>
          {offers.map((offer, index) => (
            <Dot
              key={offer.id}
              active={index === activeOfferIndex}
              onClick={() => setActiveOfferIndex(index)}
            />
          ))}
        </DotsWrapper>

        {/* ===== Salon Categories ===== */}
        {["Trending Now", "Near You", "For Her", "For Him"].map((category) => (
          <div key={category}>
            <CategoryHeader>
              <SectionTitle>{category}</SectionTitle>
            </CategoryHeader>

            <ScrollWrapper>
              <HorizontalScroll>
                {salons.map((salon: any) => (
                  <SalonCard
                    key={`${category}-${salon._id}`}
                    id={salon._id}
                    image={salon.image}
                    name={salon.name}
                    distance={salon.distance || "—"}
                    location={salon.location}
                    rating={salon.rating || 0}
                    reviews={salon.reviews || 0}
                    onClick={() => navigate(`/business/${salon._id}`, { state: salon })}
                  />
                ))}
              </HorizontalScroll>
            </ScrollWrapper>
          </div>
        ))}
      </ContentWrapper>
    </PageWrapper>
  );
};

export default HomePage;
